// EmojiSuggest.swift — GENERATED (blob) bởi Scripts/blobify-emojisuggest.py
// từ bảng dictionary (kid-words + CLDR vi/en + emojilib + hand-patch 💩…).
// KHÔNG sửa tay ngoài quy trình: sửa bảng dict gốc rồi chạy lại script.
// 2893 khóa sort theo UTF-8, binary search O(log n); giá trị là chuỗi
// emoji cách nhau bằng space, split lúc tra — không còn Dictionary ~1MB dirty
// RAM + spike build literal ở phím đầu.
import Foundation

enum EmojiSuggest {
    static func emojis(for word: String) -> [String] {
        guard !word.isEmpty else { return [] }
        // Dictionary cũ so khóa theo canonical equivalence — NFC hoá để giữ
        // hành vi với input dạng tổ hợp (NFD).
        let w = word.precomposedStringWithCanonicalMapping.lowercased()
        let q = Array(w.utf8)
        var lo = 0, hi = count
        while lo < hi {
            let mid = (lo + hi) / 2
            if cmp(mid, q) < 0 { lo = mid + 1 } else { hi = mid }
        }
        guard lo < count, cmp(lo, q) == 0 else { return [] }
        let s = Int(valOff[lo]), e = Int(valOff[lo + 1])
        return String(decoding: valBlob[s..<e], as: UTF8.self)
            .split(separator: " ").map(String.init)
    }

    private static func cmp(_ id: Int, _ q: [UInt8]) -> Int {
        var i = Int(keyOff[id])
        let end = Int(keyOff[id + 1])
        var j = 0
        while i < end && j < q.count {
            if keyBlob[i] != q[j] { return keyBlob[i] < q[j] ? -1 : 1 }
            i += 1; j += 1
        }
        if i < end { return 1 }         // khóa dài hơn query
        if j < q.count { return -1 }    // khóa ngắn hơn query
        return 0
    }

    private static let count = 2893
    private static let keyBlob: [UInt8] = Array("abcagreeairportaloalphabetamam apam nhacam traam uanan coman keman mungan rauan toian truaangelangryanhanh daoanh traianh tranganh đàoannounceantaoao phongao thunappleartaskavocadoawardbaba loba lôba ngoaiba noibabybac thangbackpackbagbaibai bienbai hatbai tapbai thoballballetbalobamboobanban beban demban khoanban phimban tayban thanban đêmbananabangbang bobang chubang tenbanhbanh mibanh ngotbaobao matbao taybao vebapbap caibasketbatbat chaobathbatterybau troibaybbqbebe boibe gaibe tibe traibeachbeanbeansbearbeardbeautifulbedbeebeetlebellben xebenhbibi dobi matbi ngobi ombi thuongbienbiet onbinhbinh hoabinh minhbirdbirthdaybiết ơnbiểnblackbloodbobo doibo raubo suaboatboc chayboiboi loibon tambonebongbong bongbong bóngbong dabong denbong hoabong tuyetboobookbooksbootboredbot bienbowbowlboxboybrainbreadbreakfastbreathebrickbridgebroombrownbuabua anbua combua sangbucbuc minhbuc tranhbucketbuffalobugbunbun bobunnybuoi sangbuoi toibuombuonbuon cuoibuon ghebuon ngubuon quabuotbutbut bibutterflybuu kienbuốtbuồnbuồn cườibuồn ghêbuồn ngủbuồn quábuổi sángbuổi tốibyebàbà ngoạibà nộibàibài hátbài thơbài tậpbàn phímbàn taybánhbánh mìbánh ngọtbáobátbát cháobãi biểnbãobébé gáibé traibé tíbìnhbình hoabình minhbíbí mậtbí ngôbí đỏbòbò sữabóngbóng đábóng đènbông hoabông tuyếtbúabúnbún bòbútbút bibăn khoănbăngbăng bóbơbơibơi lộibưu kiệnbướmbạnbạn bèbạn thânbảng chữbảng tênbảo mậtbảo vệbầu trờibậc thangbắpbắp cảibến xebể bơibệnhbị thươngbị ốmbọbọt biểnbốbốc cháybồn tắmbộ râubộ độibức tranhbữa cơmbữa sángbữa ănbựcbực mìnhcaca hatca hátca rica sica sĩcabbagecabinetcaicai aocai binhcai buacai cancai cuacai ghecai giuongcai guongcai luoccai muicai nocai ocai omcai quatcai thangcai thaocai thiacai tocai trongcai xocakecalendarcallcamcam cumcam diencam oncam traicameracampingcancan nhacan nhaccancelcandlecandycanhcanh baocanh cuacanh cungcaocao toccao tốccapcap doicap sachcarcardcashcatcat canhcat toccaterpillarcaucau becau cacau hoicau honcau 