    private static func decodeU32(_ b64: String) -> [UInt32] {
        let data = Data(base64Encoded: b64)!
        return data.withUnsafeBytes { raw in
            (0..<(data.count / 4)).map {
                UInt32(littleEndian: raw.loadUnaligned(fromByteOffset: $0 * 4, as: UInt32.self))
            }
        }
    }
